def awq_gemm(input: torch.Tensor, qweight: torch.Tensor, qzeros: torch.Tensor, scales: torch.Tensor, split_k_iters: int) -> torch.Tensor:
    if envs.VLLM_USE_TRITON_AWQ:
        from vllm.model_executor.layers.quantization.awq_triton import awq_gemm_triton
        return awq_gemm_triton(input, qweight, qzeros, scales, split_k_iters)
    return torch.ops._C.awq_gemm(input, qweight, qzeros, scales, split_k_iters)

def awq_dequantize(qweight: torch.Tensor, scales: torch.Tensor, zeros: torch.Tensor, split_k_iters: int, thx: int, thy: int) -> torch.Tensor:
    if envs.VLLM_USE_TRITON_AWQ:
        from vllm.model_executor.layers.quantization.awq_triton import awq_dequantize_triton
        return awq_dequantize_triton(qweight, scales, zeros)
    return torch.ops._C.awq_dequantize(qweight, scales, zeros, split_k_iters, thx, thy)

def rms_norm(out: torch.Tensor, input: torch.Tensor, weight: torch.Tensor, epsilon: float) -> None:
    input_contiguous = input.contiguous()
    torch.ops._C.rms_norm(out, input_contiguous, weight, epsilon)

class AWQConfig(QuantizationConfig):

    def __init__(self, weight_bits: int, group_size: int, zero_point: bool, modules_to_not_convert: Optional[list[str]]=None) -> None:
        super().__init__()
        self.weight_bits = weight_bits
        self.group_size = group_size
        self.zero_point = zero_point
        self.modules_to_not_convert = modules_to_not_convert or []
        if self.weight_bits != 4:
            raise ValueError(f'Currently, only 4-bit weight quantization is supported for AWQ, but got {self.weight_bits} bits.')
        self.pack_factor = 32 // self.weight_bits

    def __repr__(self) -> str:
        return f'AWQConfig(weight_bits={self.weight_bits}, group_size={self.group_size}, zero_point={self.zero_point}, modules_to_not_convert={self.modules_to_not_convert})'

    def get_name(self) -> QuantizationMethods:
        return 'awq'

    def get_supported_act_dtypes(self) -> list[torch.dtype]:
        return [torch.half]

    @classmethod
    def get_min_capability(cls) -> int:
        return 75

    @staticmethod
    def get_config_filenames() -> list[str]:
        return ['quant_config.json', 'quantize_config.json']

    @classmethod
    def from_config(cls, config: dict[str, Any]) -> 'AWQConfig':
        weight_bits = cls.get_from_keys(config, ['w_bit', 'bits'])
        group_size = cls.get_from_keys(config, ['q_group_size', 'group_size'])
        zero_point = cls.get_from_keys(config, ['zero_point'])
        modules_to_not_convert = cls.get_from_keys_or(config, ['modules_to_not_convert'], None)
        return cls(weight_bits, group_size, zero_point, modules_to_not_convert)

    def get_quant_method(self, layer: torch.nn.Module, prefix: str) -> Optional[Union['LinearMethodBase', 'QuantizeMethodBase']]:
        if isinstance(layer, LinearBase):
            if is_layer_skipped_awq(prefix, self.modules_to_not_convert):
                return UnquantizedLinearMethod()
            return AWQLinearMethod(self)
        elif isinstance(layer, FusedMoE):
            from .awq_marlin import AWQMarlinConfig, AWQMoEMethod
            from .moe_wna16 import MoeWNA16Config
            from .utils.marlin_utils import check_moe_marlin_supports_layer
            if not check_moe_marlin_supports_layer(layer, self.group_size):
                logger.warning_once(f"Layer '{prefix}' is not supported by AWQMoeMarlin. Falling back to Moe WNA16 kernels.")
                config = {'quant_method': 'awq', 'bits': self.weight_bits, 'group_size': self.group_size, 'zero_point': self.zero_point, 'lm_head': False}
                return MoeWNA16Config.from_config(config).get_quant_method(layer, prefix)
            marlin_compatible_config_dict = {'quant_method': 'awq', 'bits': self.weight_bits, 'group_size': self.group_size, 'zero_point': self.zero_point, 'lm_head': False, 'modules_to_not_convert': self.modules_to_not_convert}
            awq_marlin_config = AWQMarlinConfig.from_config(marlin_compatible_config_dict)
            return AWQMoEMethod(awq_marlin_config, layer.moe_config)
        return None

def apply(self, layer: torch.nn.Module, x: torch.Tensor, bias: Optional[torch.Tensor]=None) -> torch.Tensor:
    qweight = layer.qweight
    scales = layer.scales
    qzeros = layer.qzeros
    pack_factor = self.quant_config.pack_factor
    out_shape = x.shape[:-1] + (qweight.shape[-1] * pack_factor,)
    reshaped_x = x.reshape(-1, x.shape[-1])
    FP16_MATMUL_HEURISTIC_CONDITION = x.shape[:-1].numel() >= 256
    if FP16_MATMUL_HEURISTIC_CONDITION:
        out = ops.awq_dequantize(qweight, scales, qzeros, 0, 0, 0)
        out = torch.matmul(reshaped_x, out)
    else:
        out = ops.awq_gemm(reshaped_x, qweight, scales, qzeros, pack_factor)
    if bias is not None:
        out.add_(bias)
    return out.reshape(out_shape)

def forward_native(self, input_):
    if self.tp_size > 1:
        masked_input, input_mask = get_masked_input_and_mask(input_, self.shard_indices.org_vocab_start_index, self.shard_indices.org_vocab_end_index, self.shard_indices.num_org_vocab_padding, self.shard_indices.added_vocab_start_index, self.shard_indices.added_vocab_end_index)
    else:
        masked_input = input_
    output_parallel = self.quant_method.embedding(self, masked_input.long())
    if self.tp_size > 1:
        output_parallel.masked_fill_(input_mask.unsqueeze(-1), 0)
    output = tensor_model_parallel_all_reduce(output_parallel)
    return output

def forward(self, input_):
    del input_
    raise RuntimeError("LMHead's weights should be used in the sampler.")

def forward(self, input_) -> Union[torch.Tensor, tuple[torch.Tensor, Optional[Parameter]]]:
    bias = self.bias if not self.skip_bias_add else None
    assert self.quant_method is not None
    output_parallel = self.quant_method.apply(self, input_, bias)
    if self.gather_output and self.tp_size > 1:
        output = tensor_model_parallel_all_gather(output_parallel)
    else:
        output = output_parallel
    output_bias = self.bias if self.skip_bias_add else None
    if not self.return_bias:
        return output
    return (output, output_bias)

def weight_loader(self, param: Parameter, loaded_weight: torch.Tensor, loaded_shard_id: Optional[str]=None):
    is_gguf_weight = getattr(param, 'is_gguf_weight', False)
    is_gguf_weight_type = getattr(param, 'is_gguf_weight_type', False)
    if is_gguf_weight_type:
        idx_map = {'q': 0, 'k': 1, 'v': 2}
        if loaded_shard_id is not None:
            param.data[idx_map[loaded_shard_id]].copy_(loaded_weight)
            param.shard_weight_type[loaded_shard_id] = loaded_weight.item()
        else:
            param.shard_weight_type = {k: loaded_weight.item() for k in idx_map}
        return
    if is_gguf_weight:
        output_dim = getattr(param, 'output_dim', None)
        shard_size = loaded_weight.size(output_dim) // self.tp_size
        start_idx = self.tp_rank * shard_size
        if loaded_shard_id is not None:
            loaded_weight = loaded_weight.narrow(output_dim, start_idx, shard_size)
            param.shard_id.append(loaded_shard_id)
            param.shard_id_map[loaded_shard_id] = len(param.data_container)
            param.data_container.append(loaded_weight)
            return
    param_data = param.data
    output_dim = getattr(param, 'output_dim', None)
    needs_scalar_to_array = getattr(param, 'needs_scalar_to_array', False)
    if loaded_shard_id is None:
        if output_dim is None:
            if needs_scalar_to_array:
                param_data, loaded_weight = adjust_scalar_to_fused_array(param_data, loaded_weight, 0)
            assert param_data.shape == loaded_weight.shape
            param_data.copy_(loaded_weight)
            return
        shard_offsets = [('q', 0, self.total_num_heads * self.head_size), ('k', self.total_num_heads * self.head_size, self.total_num_kv_heads * self.head_size), ('v', (self.total_num_heads + self.total_num_kv_heads) * self.head_size, self.total_num_kv_heads * self.head_size)]
        use_bitsandbytes_4bit = getattr(param, 'use_bitsandbytes_4bit', False)
        packed_dim = getattr(param, 'packed_dim', None)
        for shard_id, shard_offset, shard_size in shard_offsets:
            if packed_dim == output_dim:
                shard_size = shard_size // param.packed_factor
                shard_offset = shard_offset // param.packed_factor
                shard_size, shard_offset = adjust_marlin_shard(param, shard_size, shard_offset)
            if use_bitsandbytes_4bit:
                orig_qkv_offsets = {'q': (0, self.total_num_heads * self.head_size), 'k': (self.total_num_heads * self.head_size, self.total_num_kv_heads * self.head_size), 'v': ((self.total_num_heads + self.total_num_kv_heads) * self.head_size, self.total_num_kv_heads * self.head_size), 'total': ((self.total_num_heads + 2 * self.total_num_kv_heads) * self.head_size, 0)}
                shard_size, shard_offset = adjust_bitsandbytes_4bit_shard(param, orig_qkv_offsets, shard_id)
            loaded_weight_shard = loaded_weight.narrow(output_dim, shard_offset, shard_size)
            self.weight_loader(param, loaded_weight_shard, shard_id)
        return
    assert loaded_shard_id in ['q', 'k', 'v']
    if output_dim is not None:
        if loaded_shard_id == 'q':
            shard_offset = 0
            shard_size = self.num_heads * self.head_size
        elif loaded_shard_id == 'k':
            shard_offset = self.num_heads * self.head_size
            shard_size = self.num_kv_heads * self.head_size
        elif loaded_shard_id == 'v':
            shard_offset = (self.num_heads + self.num_kv_heads) * self.head_size
            shard_size = self.num_kv_heads * self.head_size
        packed_dim = getattr(param, 'packed_dim', None)
        if packed_dim == output_dim:
            shard_size = shard_size // param.packed_factor
            shard_offset = shard_offset // param.packed_factor
            shard_size, shard_offset = adjust_marlin_shard(param, shard_size, shard_offset)
        use_bitsandbytes_4bit = getattr(param, 'use_bitsandbytes_4bit', False)
        is_sharded_weight = getattr(param, 'is_sharded_weight', False)
        is_sharded_weight = is_sharded_weight or use_bitsandbytes_4bit
        if use_bitsandbytes_4bit:
            orig_qkv_offsets = {'q': (0, self.num_heads * self.head_size), 'k': (self.num_heads * self.head_size, self.num_kv_heads * self.head_size), 'v': ((self.num_heads + self.num_kv_heads) * self.head_size, self.num_kv_heads * self.head_size), 'total': ((self.num_heads + 2 * self.num_kv_heads) * self.head_size, 0)}
            shard_size, shard_offset = adjust_bitsandbytes_4bit_shard(param, orig_qkv_offsets, loaded_shard_id)
        param_data = param_data.narrow(output_dim, shard_offset, shard_size)
        if loaded_shard_id == 'q':
            shard_id = self.tp_rank
        else:
            shard_id = self.tp_rank // self.num_kv_head_replicas
        start_idx = shard_id * shard_size
        if not is_sharded_weight:
            loaded_weight = loaded_weight.narrow(output_dim, start_idx, shard_size)
    elif needs_scalar_to_array:
        param_data, loaded_weight = adjust_scalar_to_fused_array(param_data, loaded_weight, loaded_shard_id)
    else:
        ignore_warning = getattr(param, 'ignore_warning', False)
        if not ignore_warning:
            logger.warning('Loading a weight without `output_dim` attribute in QKVParallelLinear, assume the weight is the same for all partitions.')
    assert param_data.shape == loaded_weight.shape
    param_data.copy_(loaded_weight)

def forward(self, input_) -> Union[torch.Tensor, tuple[torch.Tensor, Optional[Parameter]]]:
    if self.input_is_parallel:
        input_parallel = input_
    else:
        splitted_input = split_tensor_along_last_dim(input_, num_partitions=self.tp_size)
        input_parallel = splitted_input[self.tp_rank].contiguous()
    assert self.quant_method is not None
    bias_ = None if self.tp_rank > 0 or self.skip_bias_add else self.bias
    output_parallel = self.quant_method.apply(self, input_parallel, bias_)
    if self.reduce_results and self.tp_size > 1:
        output = tensor_model_parallel_all_reduce(output_parallel)
    else:
        output = output_parallel
    output_bias = self.bias if self.skip_bias_add else None
    if not self.return_bias:
        return output
    return (output, output_bias)

def forward_native(self, x: torch.Tensor, residual: Optional[torch.Tensor]=None) -> Union[torch.Tensor, tuple[torch.Tensor, torch.Tensor]]:
    orig_dtype = x.dtype
    x = x.to(torch.float32)
    if residual is not None:
        x = x + residual.to(torch.float32)
        residual = x.to(orig_dtype)
    hidden_size = x.shape[-1]
    if hidden_size != self.hidden_size:
        raise ValueError(f'Expected hidden_size to be {self.hidden_size}, but found: {hidden_size}')
    if self.variance_size_override is None:
        x_var = x
    else:
        if hidden_size < self.variance_size_override:
            raise ValueError(f'Expected hidden_size to be at least {self.variance_size_override}, but found: {hidden_size}')
        x_var = x[:, :, :self.variance_size_override]
    variance = x_var.pow(2).mean(dim=-1, keepdim=True)
    x = x * torch.rsqrt(variance + self.variance_epsilon)
    x = x.to(orig_dtype)
    if self.has_weight:
        x = x * self.weight
    if residual is None:
        return x
    else:
        return (x, residual)

def forward_cuda(self, x: torch.Tensor, residual: Optional[torch.Tensor]=None) -> Union[torch.Tensor, tuple[torch.Tensor, torch.Tensor]]:
    if self.variance_size_override is not None:
        return self.forward_native(x, residual)
    add_residual = residual is not None
    if add_residual:
        return fused_add_rms_norm(x, residual, self.weight.data, self.variance_epsilon)
    else:
        return rms_norm(x, self.weight.data, self.variance_epsilon)

def get_rope(head_size: int, rotary_dim: int, max_position: int, base: float, is_neox_style: bool=True, rope_scaling: Optional[dict[str, Any]]=None, dtype: Optional[torch.dtype]=None, partial_rotary_factor: float=1.0, dual_chunk_attention_config: Optional[dict[str, Any]]=None) -> RotaryEmbedding:
    if dtype is None:
        dtype = torch.get_default_dtype()
    if rope_scaling is not None:
        rope_scaling_tuple = {k: tuple(v) if isinstance(v, list) else v for k, v in rope_scaling.items()}
        rope_scaling_args = tuple(rope_scaling_tuple.items())
    else:
        rope_scaling_args = None
    if dual_chunk_attention_config is not None:
        dual_chunk_attention_tuple = {k: tuple(v) if isinstance(v, list) else v for k, v in dual_chunk_attention_config.items() if k != 'sparse_attention_config'}
        dual_chunk_attention_args = tuple(dual_chunk_attention_tuple.items())
    else:
        dual_chunk_attention_args = None
    if partial_rotary_factor < 1.0:
        rotary_dim = int(rotary_dim * partial_rotary_factor)
    key = (head_size, rotary_dim, max_position, base, is_neox_style, rope_scaling_args, dual_chunk_attention_args, dtype)
    if key in _ROPE_DICT:
        return _ROPE_DICT[key]
    if dual_chunk_attention_config is not None:
        extra_kwargs = {k: v for k, v in dual_chunk_attention_config.items() if k in ('chunk_size', 'local_size')}
        rotary_emb = DualChunkRotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, dtype, **extra_kwargs)
    elif not rope_scaling:
        rotary_emb = RotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, dtype)
    else:
        scaling_type = rope_scaling['rope_type']
        if scaling_type == 'llama3':
            scaling_factor = rope_scaling['factor']
            low_freq_factor = rope_scaling['low_freq_factor']
            high_freq_factor = rope_scaling['high_freq_factor']
            original_max_position = rope_scaling['original_max_position_embeddings']
            rotary_emb = Llama3RotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, dtype, scaling_factor, low_freq_factor, high_freq_factor, original_max_position)
        elif scaling_type == 'mllama4':
            rotary_emb = Llama4VisionRotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, dtype)
        elif scaling_type == 'default':
            if 'mrope_section' in rope_scaling:
                rotary_emb = MRotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, dtype, mrope_section=rope_scaling['mrope_section'], mrope_interleaved=rope_scaling.get('mrope_interleaved', False))
            else:
                rotary_emb = RotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, dtype)
        elif scaling_type == 'linear':
            scaling_factor = rope_scaling['factor']
            rotary_emb = LinearScalingRotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, scaling_factor, dtype)
        elif scaling_type == 'ntk':
            scaling_factor = rope_scaling['factor']
            mixed_b = rope_scaling.get('mixed_b', None)
            rotary_emb = NTKScalingRotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, scaling_factor, dtype, mixed_b)
        elif scaling_type == 'dynamic':
            if 'alpha' in rope_scaling:
                scaling_alpha = rope_scaling['alpha']
                rotary_emb = DynamicNTKAlphaRotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, scaling_alpha, dtype)
            elif 'factor' in rope_scaling:
                scaling_factor = rope_scaling['factor']
                rotary_emb = DynamicNTKScalingRotaryEmbedding(head_size, rotary_dim, max_position, base, is_neox_style, scaling_factor, dtype)
            else:
                raise ValueError("Dynamic rope scaling must contain either 'alpha' or 'factor' field")
        elif scaling_type == 'yarn':
            scaling_factor = rope_scaling['factor']
            original_max_position = rope_scaling['original_max_position_embeddings']
            extra_kwargs = {k: v for k, v in rope_scaling.items() if k in ('extrapolation_factor', 'attn_factor', 'beta_fast', 'beta_slow')}
            if 'mrope_section' in rope_scaling:
                rotary_emb = MRotaryEmbedding(head_size, rotary_dim, original_max_position, base, is_neox_style, dtype, mrope_section=rope_scaling['mrope_section'], mrope_interleaved=rope_scaling.get('mrope_interleaved', False), scaling_factor=scaling_factor, **extra_kwargs)
            else:
                rotary_emb = YaRNScalingRotaryEmbedding(head_size, rotary_dim, original_max_position, base, is_neox_style, scaling_factor, dtype, **extra_kwargs)
        elif scaling_type == 'deepseek_yarn':
            scaling_factor = rope_scaling['factor']
            original_max_position = rope_scaling['original_max_position_embeddings']
            extra_kwargs = {k: v for k, v in rope_scaling.items() if k in ('extrapolation_factor', 'attn_factor', 'beta_fast', 'beta_slow', 'mscale', 'mscale_all_dim')}
            rotary_emb = DeepseekScalingRotaryEmbedding(head_size, rotary_dim, original_max_position, base, is_neox_style, scaling_factor, dtype, **extra_kwargs)
        elif scaling_type == 'longrope':
            short_factor = rope_scaling['short_factor']
            long_factor = rope_scaling['long_factor']
            original_max_position = rope_scaling['original_max_position_embeddings']
            extra_kwargs = {k: v for k, v in rope_scaling.items() if k in ('short_mscale', 'long_mscale')}
            rotary_emb = Phi3LongRoPEScaledRotaryEmbedding(head_size, rotary_dim, max_position, original_max_position, base, is_neox_style, dtype, short_factor, long_factor, **extra_kwargs)
        else:
            raise ValueError(f'Unknown RoPE scaling type {scaling_type}')
    _ROPE_DICT[key] = rotary_emb
    return rotary_emb

def _compute_inv_freq(self, base: float) -> torch.Tensor:
    inv_freq = 1.0 / base ** (torch.arange(0, self.rotary_dim, 2, dtype=torch.float) / self.rotary_dim)
    return inv_freq

def forward_cuda(self, positions: torch.Tensor, query: torch.Tensor, key: Optional[torch.Tensor]=None) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    if self.use_flashinfer:
        torch.ops.vllm.flashinfer_rotary_embedding(positions, query, key, self.head_size, self.cos_sin_cache, self.is_neox_style)
        return (query, key)
    from vllm import _custom_ops as ops
    self._match_cos_sin_cache_dtype(query)
    ops.rotary_embedding(positions, query, key, self.head_size, self.cos_sin_cache, self.is_neox_style)
    return (query, key)

def forward_native(self, x: torch.Tensor) -> torch.Tensor:
    d = x.shape[-1] // 2
    return F.silu(x[..., :d]) * x[..., d:]

def forward(self, query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, output_shape: Optional[torch.Size]=None) -> torch.Tensor:
    if self.calculate_kv_scales:
        attn_metadata = get_forward_context().attn_metadata
        if attn_metadata.enable_kv_scales_calculation:
            self.calc_kv_scales(query, key, value)
    output_dtype = query.dtype
    if self.query_quant is not None:
        assert self.kv_cache_dtype in {'fp8', 'fp8_e4m3'}
        query, _ = self.query_quant(query, self._q_scale)
    if self.use_output:
        output_shape = output_shape if output_shape is not None else query.shape
        output = torch.zeros(output_shape, dtype=output_dtype, device=query.device)
        hidden_size = output_shape[-1]
        if not self.use_mla:
            query = query.view(-1, self.num_heads, self.head_size)
            output = output.view(-1, self.num_heads, self.head_size)
            if key is not None:
                key = key.view(-1, self.num_kv_heads, self.head_size)
            if value is not None:
                value = value.view(-1, self.num_kv_heads, self.head_size)
        if self.use_direct_call:
            forward_context: ForwardContext = get_forward_context()
            attn_metadata = forward_context.attn_metadata
            if isinstance(attn_metadata, dict):
                attn_metadata = attn_metadata[self.layer_name]
            self_kv_cache = self.kv_cache[forward_context.virtual_engine]
            self.impl.forward(self, query, key, value, self_kv_cache, attn_metadata, output=output)
        else:
            torch.ops.vllm.unified_attention_with_output(query, key, value, output, self.layer_name)
        return output.view(-1, hidden_size)
    elif self.use_direct_call:
        forward_context = get_forward_context()
        attn_metadata = forward_context.attn_metadata
        if isinstance(attn_metadata, dict):
            attn_metadata = attn_metadata[self.layer_name]
        self_kv_cache = self.kv_cache[forward_context.virtual_engine]
        return self.impl.forward(self, query, key, value, self_kv_cache, attn_metadata)
    else:
        return torch.ops.vllm.unified_attention(query, key, value, self.layer_name)

def forward(self, positions: torch.Tensor, hidden_states: torch.Tensor, residual: Optional[torch.Tensor]) -> tuple[torch.Tensor, torch.Tensor]:
    if residual is None:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
    else:
        hidden_states, residual = self.input_layernorm(hidden_states, residual)
    hidden_states = self.self_attn(positions=positions, hidden_states=hidden_states)
    hidden_states, residual = self.post_attention_layernorm(hidden_states, residual)
    hidden_states = self.mlp(hidden_states)
    return (hidden_states, residual)

def forward(self, input_ids: Optional[torch.Tensor], positions: torch.Tensor, intermediate_tensors: Optional[IntermediateTensors], inputs_embeds: Optional[torch.Tensor]=None) -> Union[torch.Tensor, IntermediateTensors, tuple[torch.Tensor, list[torch.Tensor]]]:
    if get_pp_group().is_first_rank:
        if inputs_embeds is not None:
            hidden_states = inputs_embeds
        else:
            hidden_states = self.get_input_embeddings(input_ids)
        residual = None
    else:
        assert intermediate_tensors is not None
        hidden_states = intermediate_tensors['hidden_states']
        residual = intermediate_tensors['residual']
    aux_hidden_states = []
    for idx, layer in enumerate(islice(self.layers, self.start_layer, self.end_layer)):
        if idx in self.aux_hidden_state_layers:
            aux_hidden_states.append(hidden_states + residual)
        hidden_states, residual = layer(positions, hidden_states, residual)
    if not get_pp_group().is_last_rank:
        return IntermediateTensors({'hidden_states': hidden_states, 'residual': residual})
    hidden_states, _ = self.norm(hidden_states, residual)
    if len(aux_hidden_states) > 0:
        return (hidden_states, aux_hidden_states)
    return hidden_states

def compute_logits(self, hidden_states: torch.Tensor) -> Optional[torch.Tensor]:
    logits = self.logits_processor(self.lm_head, hidden_states)
    return logits

class Mistral3ForConditionalGeneration(nn.Module, SupportsLoRA, SupportsMultiModal, SupportsPP):
    packed_modules_mapping = {'qkv_proj': ['q_proj', 'k_proj', 'v_proj'], 'gate_up_proj': ['gate_proj', 'up_proj']}
    hf_to_vllm_mapper = WeightsMapper(orig_to_new_prefix={'model.language_model.': 'language_model.model.', 'model.vision_tower.': 'vision_tower.', 'model.multi_modal_projector.': 'multi_modal_projector.', 'lm_head.': 'language_model.lm_head.'})

    @classmethod
    def get_placeholder_str(cls, modality: str, i: int) -> Optional[str]:
        if modality.startswith('image'):
            return None
        raise ValueError('Only image modality is supported')

    def __init__(self, *, vllm_config: VllmConfig, prefix: str='') -> None:
        super().__init__()
        config = vllm_config.model_config.hf_config
        quant_config = vllm_config.quant_config
        multimodal_config = vllm_config.model_config.multimodal_config
        self.config = config
        self.multimodal_config = multimodal_config
        if config.text_config.architectures is None and config.text_config.model_type == 'mistral':
            config.text_config.architectures = ['MistralForCausalLM']
        if config.projector_hidden_act is None and config.vision_config.hidden_act == 'gelu':
            config.projector_hidden_act = 'gelu'
        if multimodal_config.get_limit_per_prompt('image'):
            self.vision_tower = init_vision_tower_for_llava(config, quant_config, require_post_norm=False, prefix=maybe_prefix(prefix, 'vision_tower'))
            self.multi_modal_projector = Mistral3MultiModalProjector(vision_hidden_size=config.vision_config.hidden_size, text_hidden_size=config.text_config.hidden_size, projector_hidden_act=config.projector_hidden_act, spatial_merge_size=config.spatial_merge_size, patch_size=config.vision_config.patch_size, multimodal_projector_bias=config.multimodal_projector_bias, quant_config=quant_config, prefix=maybe_prefix(prefix, 'multi_modal_projector'))
        else:
            self.vision_tower = None
            self.multi_modal_projector = None
        self.language_model = init_vllm_registered_model(vllm_config=vllm_config, hf_config=config.text_config, prefix=maybe_prefix(prefix, 'language_model'))
        self.make_empty_intermediate_tensors = self.language_model.make_empty_intermediate_tensors

    def _parse_and_validate_image_input(self, **kwargs: object) -> Optional[Mistral3ImagePixelInputs]:
        pixel_values = kwargs.pop('pixel_values', None)
        image_embeds = kwargs.pop('image_embeds', None)
        if pixel_values is None and image_embeds is None:
            return None
        assert pixel_values is not None
        if not isinstance(pixel_values, (torch.Tensor, list)):
            raise ValueError(f'Incorrect type of pixel values. Got type: {type(pixel_values)}')
        return Mistral3ImagePixelInputs(type='pixel_values_pixtral', pixel_values=flatten_bn(pixel_values))

    def _process_image_input(self, image_input: Mistral3ImagePixelInputs) -> Union[torch.Tensor, tuple[torch.Tensor, ...]]:
        if image_input['type'] == 'image_embeds':
            return image_input['data']
        image_sizes = [(img.shape[-2], img.shape[-1]) for img in image_input['pixel_values']]
        image_features = self.vision_tower(image_input['pixel_values'])
        if isinstance(image_features, torch.Tensor):
            return self.multi_modal_projector(image_features, image_sizes)
        feature_sizes = [image_feature.shape[0] // self.config.spatial_merge_size ** 2 for image_feature in image_features]
        image_embeds = self.multi_modal_projector(torch.cat(image_features), image_sizes)
        if len(feature_sizes) > 1:
            image_embeds = torch.split(image_embeds, feature_sizes)
        else:
            image_embeds = (image_embeds,)
        return image_embeds

    def get_language_model(self) -> torch.nn.Module:
        return self.language_model

    def get_multimodal_embeddings(self, **kwargs: object) -> MultiModalEmbeddings:
        image_input = self._parse_and_validate_image_input(**kwargs)
        if image_input is None:
            return []
        vision_embeddings = self._process_image_input(image_input)
        return vision_embeddings

    def get_input_embeddings(self, input_ids: torch.Tensor, multimodal_embeddings: Optional[MultiModalEmbeddings]=None) -> torch.Tensor:
        inputs_embeds = self.language_model.get_input_embeddings(input_ids)
        if multimodal_embeddings is not None and len(multimodal_embeddings) != 0:
            inputs_embeds = merge_multimodal_embeddings(input_ids, inputs_embeds, multimodal_embeddings, self.config.image_token_index)
        return inputs_embeds

    def forward(self, input_ids: torch.Tensor, positions: torch.Tensor, intermediate_tensors: Optional[IntermediateTensors]=None, inputs_embeds: Optional[torch.Tensor]=None, **kwargs: object) -> Union[torch.Tensor, IntermediateTensors]:
        if intermediate_tensors is not None:
            inputs_embeds = None
        elif inputs_embeds is None:
            vision_embeddings = self.get_multimodal_embeddings(**kwargs)
            inputs_embeds = self.get_input_embeddings(input_ids, vision_embeddings)
            input_ids = None
        hidden_states = self.language_model.model(input_ids, positions, intermediate_tensors, inputs_embeds=inputs_embeds)
        return hidden_states

    def compute_logits(self, hidden_states: torch.Tensor) -> Optional[torch.Tensor]:
        return self.language_model.compute_logits(hidden_states)

    def load_weights(self, weights: Iterable[tuple[str, torch.Tensor]]) -> set[str]:
        skip_prefixes = []
        if self.vision_tower is None and self.multi_modal_projector is None:
            skip_prefixes = ['vision_tower.', 'multi_modal_projector.']
        loader = AutoWeightsLoader(self, skip_prefixes=skip_prefixes)
        return loader.load_weights(weights, mapper=self.hf_to_vllm_mapper)

    def get_mm_mapping(self) -> MultiModelKeys:
        return MultiModelKeys.from_string_field(language_model='language_model', connector='multi_modal_projector', tower_model='vision_tower')

def forward(self, lm_head: VocabParallelEmbedding, hidden_states: torch.Tensor, embedding_bias: Optional[torch.Tensor]=None) -> Optional[torch.Tensor]:
    if self.logits_as_input:
        logits = hidden_states
    else:
        logits = self._get_logits(hidden_states, lm_head, embedding_bias)
    if logits is not None:
        if self.soft_cap is not None:
            logits = logits / self.soft_cap
            logits = torch.tanh(logits)
            logits = logits * self.soft_cap
        if self.scale != 1.0:
            logits *= self.scale
    return logits

def _get_logits(self, hidden_states: torch.Tensor, lm_head: VocabParallelEmbedding, embedding_bias: Optional[torch.Tensor]) -> Optional[torch.Tensor]:
    logits = lm_head.quant_method.apply(lm_head, hidden_states, bias=embedding_bias)
    logits = self._gather_logits(logits)
    if logits is not None:
        logits = logits[..., :self.org_vocab_size]
    return logits

def sample(self, logits: torch.Tensor, sampling_metadata: SamplingMetadata) -> tuple[torch.Tensor, Optional[torch.Tensor]]:
    assert not (sampling_metadata.all_greedy and sampling_metadata.all_random)
    if sampling_metadata.all_random:
        greedy_sampled = None
    else:
        greedy_sampled = self.greedy_sample(logits)
        if sampling_metadata.all_greedy:
            processed_logprobs = None
            if sampling_metadata.max_num_logprobs is not None:
                if self.logprobs_mode == 'processed_logits':
                    processed_logprobs = logits
                elif self.logprobs_mode == 'processed_logprobs':
                    processed_logprobs = self.compute_logprobs(logits)
            return (greedy_sampled, processed_logprobs)
    assert sampling_metadata.temperature is not None
    logits = self.apply_temperature(logits, sampling_metadata.temperature, sampling_metadata.all_random)
    for processor in sampling_metadata.logitsprocs.argmax_invariant:
        logits = processor.apply(logits)
    random_sampled, processed_logprobs = self.topk_topp_sampler(logits, sampling_metadata.generators, sampling_metadata.top_k, sampling_metadata.top_p)
    if greedy_sampled is None:
        return (random_sampled, processed_logprobs)
    sampled = torch.where(sampling_metadata.temperature < _SAMPLING_EPS, greedy_sampled, random_sampled, out=greedy_sampled)
    return (sampled, processed_logprobs)

def _load_logitsprocs_by_fqcns(logits_processors: Optional[Sequence[Union[str, type[LogitsProcessor]]]]) -> list[type[LogitsProcessor]]:
    if not logits_processors:
        return []
    logger.debug('%s additional custom logits processors specified, checking whether they need to be loaded.', len(logits_processors))
    classes: list[type[LogitsProcessor]] = []
    for ldx, logitproc in enumerate(logits_processors):
        if isinstance(logitproc, type):
            logger.debug(' - Already-loaded logit processor: %s', logitproc.__name__)
            if not issubclass(logitproc, LogitsProcessor):
                raise ValueError(f'{logitproc.__name__} is not a subclass of LogitsProcessor')
            classes.append(logitproc)
            continue
        logger.debug('- Loading logits processor %s', logitproc)
        module_path, qualname = logitproc.split(':')
        try:
            module = importlib.import_module(module_path)
        except Exception as e:
            raise RuntimeError(f'Failed to load {ldx}th LogitsProcessor plugin {logitproc}') from e
        obj = module
        for attr in qualname.split('.'):
            obj = getattr(obj, attr)
        if not isinstance(obj, type):
            raise ValueError('Loaded logit processor must be a type.')
        if not issubclass(obj, LogitsProcessor):
            raise ValueError(f'{obj.__name__} must be a subclass of LogitsProcessor')
        classes.append(obj)
    return classes

def process_outputs(self, engine_core_outputs: list[EngineCoreOutput], engine_core_timestamp: Optional[float]=None, iteration_stats: Optional[IterationStats]=None) -> OutputProcessorOutput:
    request_outputs: Union[list[RequestOutput], list[PoolingRequestOutput]] = []
    reqs_to_abort: list[str] = []
    for engine_core_output in engine_core_outputs:
        req_id = engine_core_output.request_id
        req_state = self.request_states.get(req_id)
        if req_state is None:
            continue
        self._update_stats_from_output(req_state, engine_core_output, engine_core_timestamp, iteration_stats)
        new_token_ids = engine_core_output.new_token_ids
        pooling_output = engine_core_output.pooling_output
        finish_reason = engine_core_output.finish_reason
        stop_reason = engine_core_output.stop_reason
        kv_transfer_params = engine_core_output.kv_transfer_params
        req_state.num_cached_tokens = engine_core_output.num_cached_tokens
        req_state.is_prefilling = False
        if pooling_output is None:
            assert req_state.detokenizer is not None
            assert req_state.logprobs_processor is not None
            stop_string = req_state.detokenizer.update(new_token_ids, finish_reason == FinishReason.STOP)
            if stop_string:
                finish_reason = FinishReason.STOP
                stop_reason = stop_string
            req_state.logprobs_processor.update_from_output(engine_core_output)
        if (request_output := req_state.make_request_output(new_token_ids, pooling_output, finish_reason, stop_reason, kv_transfer_params)):
            if req_state.queue is not None:
                req_state.queue.put(request_output)
            else:
                request_outputs.append(request_output)
        if finish_reason is not None:
            self.request_states.pop(req_id)
            parent_req = req_state.parent_req
            if parent_req and (not parent_req.child_requests):
                self.parent_requests.pop(parent_req.request_id, None)
            if not engine_core_output.finished:
                reqs_to_abort.append(req_id)
            self._update_stats_from_finished(req_state, finish_reason, iteration_stats)
            if self.tracer:
                self.do_tracing(engine_core_output, req_state, iteration_stats)
    self.lora_states.update_iteration_stats(iteration_stats)
    return OutputProcessorOutput(request_outputs=request_outputs, reqs_to_abort=reqs_to_abort)

def update_from_output(self, scheduler_output: SchedulerOutput, model_runner_output: ModelRunnerOutput) -> dict[int, EngineCoreOutputs]:
    sampled_token_ids = model_runner_output.sampled_token_ids
    logprobs = model_runner_output.logprobs
    prompt_logprobs_dict = model_runner_output.prompt_logprobs_dict
    num_scheduled_tokens = scheduler_output.num_scheduled_tokens
    pooler_outputs = model_runner_output.pooler_output
    num_nans_in_logits = model_runner_output.num_nans_in_logits
    kv_connector_output = model_runner_output.kv_connector_output
    outputs: dict[int, list[EngineCoreOutput]] = defaultdict(list)
    spec_decoding_stats: Optional[SpecDecodingStats] = None
    kv_connector_stats = kv_connector_output.kv_connector_stats if kv_connector_output else None
    stopped_running_reqs: set[Request] = set()
    stopped_preempted_reqs: set[Request] = set()
    for req_id, num_tokens_scheduled in num_scheduled_tokens.items():
        assert num_tokens_scheduled > 0
        request = self.requests.get(req_id)
        if request is None:
            continue
        req_index = model_runner_output.req_id_to_index[req_id]
        generated_token_ids = sampled_token_ids[req_index] if sampled_token_ids else []
        scheduled_spec_token_ids = scheduler_output.scheduled_spec_decode_tokens.get(req_id)
        if scheduled_spec_token_ids:
            num_draft_tokens = len(scheduled_spec_token_ids)
            num_accepted = len(generated_token_ids) - 1
            num_rejected = num_draft_tokens - num_accepted
            request.num_computed_tokens -= num_rejected
            spec_decoding_stats = self.make_spec_decoding_stats(spec_decoding_stats, num_draft_tokens=num_draft_tokens, num_accepted_tokens=num_accepted)
        stopped = False
        new_logprobs = None
        new_token_ids = generated_token_ids
        kv_transfer_params = None
        status_before_stop = request.status
        if new_token_ids:
            new_token_ids, stopped = self._update_request_with_output(request, new_token_ids)
        pooler_output = None
        if pooler_outputs:
            pooler_output = pooler_outputs[req_index]
            stopped = check_stop(request, self.max_model_len, pooler_output)
        if stopped:
            kv_transfer_params = self._free_request(request)
            if status_before_stop == RequestStatus.RUNNING:
                stopped_running_reqs.add(request)
            else:
                stopped_preempted_reqs.add(request)
        if request.sampling_params is not None and request.sampling_params.logprobs is not None and logprobs:
            new_logprobs = logprobs.slice(req_index, req_index + 1)
        if new_token_ids and self.structured_output_manager.should_advance(request):
            request.structured_output_request.grammar.accept_tokens(req_id, new_token_ids)
        if num_nans_in_logits is not None and req_id in num_nans_in_logits:
            request.num_nans_in_logits = num_nans_in_logits[req_id]
        prompt_logprobs_tensors = prompt_logprobs_dict.get(req_id)
        if new_token_ids or pooler_output is not None or kv_transfer_params:
            outputs[request.client_index].append(EngineCoreOutput(request_id=req_id, new_token_ids=new_token_ids, finish_reason=request.get_finished_reason(), new_logprobs=new_logprobs, new_prompt_logprobs_tensors=prompt_logprobs_tensors, pooling_output=pooler_output, stop_reason=request.stop_reason, events=request.take_events(), kv_transfer_params=kv_transfer_params, trace_headers=request.trace_headers, num_cached_tokens=request.num_cached_tokens))
        else:
            assert not prompt_logprobs_tensors
    if stopped_running_reqs:
        self.running = remove_all(self.running, stopped_running_reqs)
    if stopped_preempted_reqs:
        self.waiting.remove_requests(stopped_preempted_reqs)
    if model_runner_output.kv_connector_output:
        self._update_from_kv_xfer_finished(model_runner_output.kv_connector_output)
    engine_core_outputs = {client_index: EngineCoreOutputs(outputs=outs) for client_index, outs in outputs.items()}
    finished_req_ids = self.finished_req_ids_dict
    if finished_req_ids:
        for client_index, finished_set in finished_req_ids.items():
            if (eco := engine_core_outputs.get(client_index)) is not None:
                eco.finished_requests = finished_set
            else:
                engine_core_outputs[client_index] = EngineCoreOutputs(finished_requests=finished_set)
        finished_req_ids.clear()
    if (stats := self.make_stats(spec_decoding_stats, kv_connector_stats)) is not None:
        if (eco := next(iter(engine_core_outputs.values()), None)) is None:
            engine_core_outputs[0] = eco = EngineCoreOutputs()
        eco.scheduler_stats = stats
    return engine_core_outputs

def _update_request_with_output(self, request: Request, new_token_ids: list[int]) -> tuple[list[int], bool]:
    stopped = False
    for num_new, output_token_id in enumerate(new_token_ids, 1):
        request.append_output_token_ids(output_token_id)
        stopped = check_stop(request, self.max_model_len)
        if stopped:
            del new_token_ids[num_new:]
            break
    return (new_token_ids, stopped)

def check_stop(request: Request, max_model_len: int, pooler_output: Optional[torch.Tensor]=None) -> bool:
    if request.num_tokens >= max_model_len or request.num_output_tokens >= request.max_tokens:
        request.status = RequestStatus.FINISHED_LENGTH_CAPPED
        return True
    if request.pooling_params:
        if pooler_output is not None:
            request.status = RequestStatus.FINISHED_STOPPED
            return True
        return False
    sampling_params = request.sampling_params
    assert sampling_params is not None
    last_token_id = request.output_token_ids[-1]
    if not sampling_params.ignore_eos and last_token_id == request.eos_token_id:
        request.status = RequestStatus.FINISHED_STOPPED
        return True
    if last_token_id in (sampling_params.stop_token_ids or ()):
        request.status = RequestStatus.FINISHED_STOPPED
        request.stop_reason = last_token_id
        return True
    return False

def append_output_token_ids(self, token_ids: Union[int, list[int]]) -> None:
    if isinstance(token_ids, int):
        self._output_token_ids.append(token_ids)
        self._all_token_ids.append(token_ids)
    else:
        self._output_token_ids.extend(token_ids)
        self._all_token_ids.extend(token_ids)
    if self.get_hash_new_full_blocks is not None:
        self.block_hashes.extend(self.get_hash_new_full_blocks())

def update_from_generation_config(self, generation_config: dict[str, Any], model_eos_token_id: Optional[int]=None) -> None:
    if model_eos_token_id is not None:
        self._all_stop_token_ids.add(model_eos_token_id)
    if (eos_ids := generation_config.get('eos_token_id')) is not None:
        eos_ids = {eos_ids} if isinstance(eos_ids, int) else set(eos_ids)
        if model_eos_token_id is not None:
            eos_ids.discard(model_eos_token_id)
        if eos_ids:
            self._all_stop_token_ids.update(eos_ids)
            if not self.ignore_eos:
                eos_ids.update(self.stop_token_ids)
                self.stop_token_ids = list(eos_ids)

def dispatch_unquantized_gemm() -> Callable[..., torch.Tensor]:
    if current_platform.is_rocm():
        return rocm_unquantized_gemm
    elif current_platform.is_cpu():
        return cpu_unquantized_gemm
    else:
        return default_unquantized_gemm

def get_flash_attn_version(requires_alibi: bool=False) -> Optional[int]:
    from vllm.platforms import current_platform
    if current_platform.is_xpu():
        return 2
    try:
        from vllm.vllm_flash_attn.flash_attn_interface import fa_version_unsupported_reason, is_fa_version_supported
        device_capability = current_platform.get_device_capability()
        assert device_capability is not None
        fa_version = 3 if device_capability.major == 9 and is_fa_version_supported(3) else 2
        if envs.VLLM_FLASH_ATTN_VERSION is not None:
            assert envs.VLLM_FLASH_ATTN_VERSION in [2, 3]
            fa_version = envs.VLLM_FLASH_ATTN_VERSION
        if device_capability.major == 10 and fa_version == 3:
            logger.warning_once('Cannot use FA version 3 on Blackwell platform defaulting to FA version 2.')
            fa_version = 2
        if requires_alibi and fa_version == 3:
            logger.warning_once('Cannot use FA version 3 with ALiBi, defaulting to FA version 2.')
            fa_version = 2
        if not is_fa_version_supported(fa_version):
            logger.error('Cannot use FA version %d is not supported due to %s', fa_version, fa_version_unsupported_reason(fa_version))
        assert is_fa_version_supported(fa_version)
        return fa_version
    except (ImportError, AssertionError):
        return None

def is_fa_version_supported(fa_version: int, device=None) -> bool:
    assert fa_version in [2, 3], f'Unsupported FA version: {fa_version}'
    if fa_version == 2:
        return _is_fa2_supported(device)[0]
    elif fa_version == 3:
        return _is_fa3_supported(device)[0]

def flash_attn_varlen_func(q, k, v, max_seqlen_q, cu_seqlens_q, max_seqlen_k, cu_seqlens_k=None, seqused_k=None, q_v=None, dropout_p=0.0, softmax_scale=None, causal=False, window_size: Optional[List[int]]=None, softcap=0.0, alibi_slopes=None, deterministic=False, return_attn_probs=False, block_table=None, return_softmax_lse=False, out=None, scheduler_metadata=None, q_descale=None, k_descale=None, v_descale=None, num_splits: int=0, fa_version: int=DEFAULT_FA_VERSION, s_aux=None):
    assert cu_seqlens_k is not None or seqused_k is not None, 'cu_seqlens_k or seqused_k must be provided'
    assert cu_seqlens_k is None or seqused_k is None, 'cu_seqlens_k and seqused_k cannot be provided at the same time'
    assert block_table is None or seqused_k is not None, 'seqused_k must be provided if block_table is provided'
    if softmax_scale is None:
        softmax_scale = q.shape[-1] ** (-0.5)
    real_window_size: Tuple[int, int]
    if window_size is None:
        real_window_size = (-1, -1)
    else:
        assert len(window_size) == 2
        real_window_size = (window_size[0], window_size[1])
    q, k, v = [maybe_contiguous(x) for x in (q, k, v)]
    dummy_cu_seqlens_k = torch.empty_like(cu_seqlens_q)
    if fa_version == 2:
        if scheduler_metadata is not None and q_descale is not None and (k_descale is not None) and (v_descale is not None):
            raise NotImplementedError('FA2 does not support scheduler_metadata, q_descale, k_descale, v_descale')
        if s_aux is not None:
            raise NotImplementedError('FA2 does not support s_aux')
        if num_splits > 1:
            raise NotImplementedError('FA2 does not support num_splits > 1')
        out, softmax_lse = torch.ops._vllm_fa2_C.varlen_fwd(q, k, v, out, cu_seqlens_q, dummy_cu_seqlens_k if cu_seqlens_k is None else cu_seqlens_k, seqused_k, None, block_table, alibi_slopes, max_seqlen_q, max_seqlen_k, dropout_p, softmax_scale, False, causal, real_window_size[0], real_window_size[1], softcap, return_softmax_lse and dropout_p > 0, None)
    elif fa_version == 3:
        assert alibi_slopes is None, 'Alibi is not supported in FA3'
        out, softmax_lse, _, _ = torch.ops._vllm_fa3_C.fwd(q, k, v, None, None, q_v, out, cu_seqlens_q, cu_seqlens_k, None, None, seqused_k, max_seqlen_q, max_seqlen_k, block_table, None, None, None, None, None, q_descale, k_descale, v_descale, softmax_scale, causal, real_window_size[0], real_window_size[1], softcap, True, scheduler_metadata, num_splits, None, 0, s_aux)
    else:
        raise ValueError(f'Unsupported FA version: {fa_version}')
    return (out, softmax_lse) if return_softmax_lse else out

def resolve_model_cls(self, architectures: Union[str, list[str]], model_config: ModelConfig) -> tuple[type[nn.Module], str]:
    if isinstance(architectures, str):
        architectures = [architectures]
    if not architectures:
        raise ValueError('No model architectures are specified')
    if model_config.model_impl == 'transformers':
        arch = self._try_resolve_transformers(architectures[0], model_config)
        if arch is not None:
            model_cls = self._try_load_model_cls(arch)
            if model_cls is not None:
                return (model_cls, arch)
    elif model_config.model_impl == 'terratorch':
        arch = 'Terratorch'
        model_cls = self._try_load_model_cls(arch)
        if model_cls is not None:
            return (model_cls, arch)
    if all((arch not in self.models for arch in architectures)) and model_config.model_impl == 'auto' and (getattr(model_config, 'convert_type', 'none') == 'none'):
        arch = self._try_resolve_transformers(architectures[0], model_config)
        if arch is not None:
            model_cls = self._try_load_model_cls(arch)
            if model_cls is not None:
                return (model_cls, arch)
    for arch in architectures:
        normalized_arch = self._normalize_arch(arch, model_config)
        model_cls = self._try_load_model_cls(normalized_arch)
        if model_cls is not None:
            return (model_cls, arch)
    if all((arch not in self.models for arch in architectures)) and model_config.model_impl == 'auto':
        arch = self._try_resolve_transformers(architectures[0], model_config)
        if arch is not None:
            model_cls = self._try_load_model_cls(arch)
            if model_cls is not None:
                return (model_cls, arch)
    return self._raise_for_unsupported(architectures)

def _load_param(self, base_prefix: str, param: nn.Parameter, weights: Iterable[tuple[str, torch.Tensor]]) -> Iterable[str]:
    for weight_name, weight_data in weights:
        weight_qualname = self._get_qualname(base_prefix, weight_name)
        if self._can_skip(weight_qualname):
            logger.debug('Skipping weight %s', weight_qualname)
            continue
        if weight_name != '':
            if self._can_ignore_unexpected(weight_qualname):
                logger.debug('Ignoring weight %s', weight_qualname)
                continue
            raise ValueError(f"Attempted to load nested weight '{weight_qualname}' into a single parameter '{base_prefix}'")
        weight_loader = getattr(param, 'weight_loader', default_weight_loader)
        weight_loader(param, weight_data)
        logger.debug('Loaded weight %s with shape %s', weight_qualname, param.shape)
        yield weight_qualname

def _load_module(self, base_prefix: str, module: nn.Module, weights: Iterable[tuple[str, torch.Tensor]]) -> Iterable[str]:
    if isinstance(module, PPMissingLayer):
        return
    if module != self.module:
        module_load_weights = getattr(module, 'load_weights', None)
        if callable(module_load_weights):
            loaded_params = module_load_weights(weights)
            if loaded_params is None:
                logger.warning('Unable to collect loaded parameters for module %s', module)
            else:
                yield from map(lambda x: self._get_qualname(base_prefix, x), loaded_params)
    child_modules = dict(module.named_children())
    child_params = dict(module.named_parameters(recurse=False))
    self._add_loadable_non_param_tensors(module, child_params)
    for child_prefix, child_weights in self._groupby_prefix(weights):
        prefix = self._get_qualname(base_prefix, child_prefix)
        if child_prefix in child_modules:
            if self._can_skip(prefix + '.'):
                logger.debug('Skipping module %s', prefix)
                continue
            yield from self._load_module(prefix, child_modules[child_prefix], child_weights)
        elif child_prefix in child_params:
            if self._can_skip(prefix):
                logger.debug('Skipping param %s', prefix)
                continue
            yield from self._load_param(prefix, child_params[child_prefix], child_weights)
        else:
            can_skip_module = self._can_skip(prefix + '.')
            can_skip_param = self._can_skip(prefix)
            if can_skip_module or can_skip_param:
                logger.debug('Skipping missing %s', prefix)
                continue
            can_ignore_module = self._can_ignore_unexpected(prefix + '.')
            can_ignore_param = self._can_ignore_unexpected(prefix)
            if can_ignore_module or can_ignore_param:
                logger.debug('Ignoring missing %s', prefix)
                continue
            msg = f"There is no module or parameter named '{prefix}' in {type(self.module).__name__}"
            raise ValueError(msg)

def load_weights(self, weights: Iterable[tuple[str, torch.Tensor]], *, mapper: Optional[WeightsMapper]=None) -> set[str]:
    if mapper is not None:
        weights = mapper.apply(weights)
    weights = ((name, weight) for name, weight in weights if not self._can_skip(name))
    autoloaded_weights = set(self._load_module('', self.module, weights))
    return autoloaded_weights

class PPMissingLayer(torch.nn.Identity):

    def __init__(self, *args, **kwargs):
        super().__init__()

    def forward(self, *args, **kwargs):
        return args[0] if args else next(iter(kwargs.values()))

class WeightsMapper:
    orig_to_new_substr: WeightsMapping = field(default_factory=dict)
    orig_to_new_prefix: WeightsMapping = field(default_factory=dict)
    orig_to_new_suffix: WeightsMapping = field(default_factory=dict)

    def _map_name(self, key: str) -> Optional[str]:
        for substr, new_key in self.orig_to_new_substr.items():
            if substr in key:
                if new_key is None:
                    return None
                key = key.replace(substr, new_key, 1)
        for prefix, new_key in self.orig_to_new_prefix.items():
            if key.startswith(prefix):
                if new_key is None:
                    return None
                key = key.replace(prefix, new_key, 1)
        for suffix, new_key in self.orig_to_new_suffix.items():
            if key.endswith(suffix):
                if new_key is None:
                    return None
                key = new_key.join(key.rsplit(suffix, 1))
        return key

    def apply(self, weights: Iterable[tuple[str, torch.Tensor]]) -> Iterable[tuple[str, torch.Tensor]]:
        return ((out_name, data) for name, data in weights if (out_name := self._map_name(name)) is not None)

    def apply_list(self, values: list[str]) -> list[str]:
        return [out_name for name in values if (out_name := self._map_name(name)) is not None]

    def apply_dict(self, values: dict[str, Any]) -> dict[str, Any]:
        return {out_name: value for name, value in values.items() if (out_name := self._map_name(name)) is not None}

def extract_layer_index(layer_name: str, num_attn_module: int=1) -> int:
    subnames = layer_name.split('.')
    int_vals: list[int] = []
    for subname in subnames:
        try:
            int_vals.append(int(subname))
        except ValueError:
            continue
    if num_attn_module == 1 or 'attn' not in layer_name:
        assert len(int_vals) == 1, f'layer name {layer_name} should only contain one integer'
        return int_vals[0]
    else:
        assert len(int_vals) <= 2, f'layer name {layer_name} should contain most two integers'
        layer_index = int_vals[0] * num_attn_module + int_vals[1] if len(int_vals) == 2 else int_vals[0]
        return layer_index

def init_vllm_registered_model(vllm_config: VllmConfig, *, prefix: str='', hf_config: Optional[PretrainedConfig]=None, architectures: Optional[list[str]]=None) -> nn.Module:
    from vllm.model_executor.model_loader.utils import initialize_model
    if hf_config is None and architectures is not None:
        hf_config = vllm_config.model_config.hf_config
    if hf_config is not None:
        vllm_config = vllm_config.with_hf_config(hf_config, architectures=architectures)
    return initialize_model(vllm_config=vllm_config, prefix=prefix)

def is_pp_missing_parameter(name: str, model: torch.nn.Module) -> bool:
    if isinstance(model, PPMissingLayer):
        return True
    return any((name.startswith(missing_layer_name) for missing_layer_name in get_pp_missing_layer_names(model)))

def make_empty_intermediate_tensors_factory(keys: list[str], hidden_size: int):

    def make_empty_intermediate_tensors(batch_size: int, dtype: torch.dtype, device: torch.device) -> IntermediateTensors:
        return IntermediateTensors({key: torch.zeros((batch_size, hidden_size), dtype=dtype, device=device) for key in keys})
    return make_empty_intermediate_tensors

def make_layers(num_hidden_layers: int, layer_fn: LayerFn, prefix: str) -> tuple[int, int, torch.nn.ModuleList]:
    from vllm.distributed.parallel_state import get_pp_group
    from vllm.distributed.utils import get_pp_indices
    start_layer, end_layer = get_pp_indices(num_hidden_layers, get_pp_group().rank_in_group, get_pp_group().world_size)
    modules = torch.nn.ModuleList([PPMissingLayer() for _ in range(start_layer)] + [maybe_offload_to_cpu(layer_fn(prefix=f'{prefix}.{idx}')) for idx in range(start_layer, end_layer)] + [PPMissingLayer() for _ in range(end_layer, num_hidden_layers)])
    return (start_layer, end_layer, modules)

def merge_multimodal_embeddings(input_ids: torch.Tensor, inputs_embeds: torch.Tensor, multimodal_embeddings: NestedTensors, placeholder_token_id: Union[int, list[int]]) -> torch.Tensor:
    if isinstance(placeholder_token_id, list):
        placeholder_token_id = torch.tensor(placeholder_token_id, pin_memory=is_pin_memory_available()).to(device=input_ids.device, non_blocking=True)
        return _merge_multimodal_embeddings(inputs_embeds, torch.isin(input_ids, placeholder_token_id), multimodal_embeddings)
    return _merge_multimodal_embeddings(inputs_embeds, input_ids == placeholder_token_id, multimodal_embeddings)

def default_weight_loader(param: torch.Tensor, loaded_weight: torch.Tensor) -> None:
    try:
        if param.numel() == 1 and loaded_weight.numel() == 1:
            param.data.fill_(loaded_weight.item())
        else:
            assert param.size() == loaded_weight.size(), f'Attempted to load weight ({loaded_weight.size()}) into parameter ({param.size()})'
            param.data.copy_(loaded_weight)
    except Exception:
        raise

def get_quant_config(model_config: ModelConfig, load_config: LoadConfig) -> QuantizationConfig:
    quant_cls = get_quantization_config(model_config.quantization)
    if model_config.quantization in ('gguf', 'inc'):
        return quant_cls()
    hf_quant_config = getattr(model_config.hf_config, 'quantization_config', None)
    hf_text_config = getattr(model_config.hf_config, 'text_config', None)
    if hf_quant_config is None and hf_text_config is not None:
        hf_quant_config = getattr(hf_text_config, 'quantization_config', None)
    if hf_quant_config is None:
        hf_quant_config = getattr(model_config.hf_config, 'compression_config', None)
    if hf_quant_config is not None:
        return quant_cls.from_config(hf_quant_config)
    if model_config.quantization == 'bitsandbytes':
        return quant_cls.from_config({})
    model_name_or_path = maybe_download_from_modelscope(model_config.model, revision=model_config.revision, download_dir=load_config.download_dir, allow_patterns=['*.json']) or model_config.model
    is_local = os.path.isdir(model_name_or_path)
    if not is_local:
        with get_lock(model_config.model, load_config.download_dir):
            hf_folder = snapshot_download(model_config.model, revision=model_config.revision, allow_patterns='*.json', cache_dir=load_config.download_dir, local_files_only=huggingface_hub.constants.HF_HUB_OFFLINE, tqdm_class=DisabledTqdm)
    else:
        hf_folder = model_name_or_path
    possible_config_filenames = quant_cls.get_config_filenames()
    if not possible_config_filenames:
        return quant_cls()
    config_files = glob.glob(os.path.join(hf_folder, '*.json'))
    quant_config_files = [f for f in config_files if any((f.endswith(x) for x in possible_config_filenames))]
    if len(quant_config_files) == 0:
        raise ValueError(f'Cannot find the config file for {model_config.quantization}')
    if len(quant_config_files) > 1:
        raise ValueError(f'Found multiple config files for {model_config.quantization}: {quant_config_files}')
    quant_config_file = quant_config_files[0]
    with open(quant_config_file) as f:
        config = json.load(f)
        if model_config.quantization == 'bitsandbytes':
            config['adapter_name_or_path'] = model_config.model
        elif model_config.quantization == 'modelopt':
            if config['producer']['name'] == 'modelopt':
                return quant_cls.from_config(config)
            else:
                raise ValueError(f'Unsupported quantization config found for {model_config.quantization} in {f}.')
    return quant_cls.from_config(config)

def maybe_remap_kv_scale_name(name: str, params_dict: dict) -> Optional[str]:
    if name.endswith('.kv_scale'):
        logger.warning_once('DEPRECATED. Found kv_scale in the checkpoint. This format is deprecated in favor of separate k_scale and v_scale tensors and will be removed in a future release. Functionally, we will remap kv_scale to k_scale and duplicate k_scale to v_scale')
        remapped_name = name.replace('.kv_scale', '.attn.k_scale')
        if remapped_name not in params_dict:
            logger.warning_once('Found kv_scale in the checkpoint (e.g. %s), but not found the expected name in the model (e.g. %s). kv_scale is not loaded.', name, remapped_name)
            return None
        return remapped_name
    scale_mapping_patterns = [('<LOCAL_PATH>])_proj<LOCAL_PATH>])_scale$', '.self_attn.attn.<LOCAL_PATH>'), ('<LOCAL_PATH>])_scale$', '.self_attn.attn.<LOCAL_PATH>'), ('<LOCAL_PATH>])_scale$', '.self_attn.attn.<LOCAL_PATH>'), ('<LOCAL_PATH>])_scale$', '.attn.<LOCAL_PATH>')]
    if name.endswith(('.k_scale', '.v_scale')):
        import regex as re
        for pattern, replacement in scale_mapping_patterns:
            if re.search(pattern, name):
                remapped_name = re.sub(pattern, replacement, name)
                if remapped_name not in params_dict:
                    scale_type = name.split('.')[-1]
                    logger.warning_once('Found %s in the checkpoint (e.g. %s), but not found the expected name in the model (e.g. %s). %s is not loaded.', scale_type, name, remapped_name, scale_type)
                    return None
                return remapped_name
    return name

def safetensors_weights_iterator(hf_weights_files: list[str], use_tqdm_on_load: bool, safetensors_load_strategy: str='lazy') -> Generator[tuple[str, torch.Tensor], None, None]:
    loading_desc = 'Loading safetensors checkpoint shards'
    if safetensors_load_strategy == 'eager':
        loading_desc += ' (eager)'
    for st_file in tqdm(hf_weights_files, desc=loading_desc, disable=not enable_tqdm(use_tqdm_on_load), bar_format=_BAR_FORMAT):
        if safetensors_load_strategy == 'eager':
            with open(st_file, 'rb') as f:
                state_dict = load(f.read())
            yield from state_dict.items()
        else:
            with safe_open(st_file, framework='pt') as f:
                for name in f.keys():
                    param = f.get_tensor(name)
                    yield (name, param)

def backend_name_to_enum(backend_name: str) -> Optional[_Backend]:
    assert backend_name is not None
    return _Backend[backend_name] if backend_name in _Backend.__members__ else None

def _cached_get_attn_backend(head_size: int, dtype: torch.dtype, kv_cache_dtype: Optional[str], block_size: int, use_v1: bool=False, use_mla: bool=False, has_sink: bool=False, use_sparse: bool=False) -> type[AttentionBackend]:
    selected_backend = None
    backend_by_global_setting: Optional[_Backend] = get_global_forced_attn_backend()
    if backend_by_global_setting is not None:
        selected_backend = backend_by_global_setting
    else:
        backend_by_env_var: Optional[str] = envs.VLLM_ATTENTION_BACKEND
        if backend_by_env_var is not None:
            if backend_by_env_var.endswith('_VLLM_V1'):
                logger.warning("The suffix '_VLLM_V1' in the environment variable %s is no longer necessary as V0 backends have been deprecated. Please remove this suffix from your environment variable setting.", STR_BACKEND_ENV_VAR)
                backend_by_env_var = backend_by_env_var.removesuffix('_VLLM_V1')
            selected_backend = backend_name_to_enum(backend_by_env_var)
            if selected_backend is None:
                raise ValueError(f"Invalid attention backend: '{backend_by_env_var}'. Valid backends are: {list(_Backend.__members__.keys())}")
    attention_cls = current_platform.get_attn_backend_cls(selected_backend, head_size, dtype, kv_cache_dtype, block_size, use_v1, use_mla, has_sink, use_sparse)
    if not attention_cls:
        raise ValueError(f'Invalid attention backend for {current_platform.device_name}')
    return resolve_obj_by_qualname(attention_cls)

class QuantizationConfig(ABC):

    def __init__(self):
        super().__init__()
        self.packed_modules_mapping: dict[str, list[str]] = dict()

    @abstractmethod
    def get_name(self) -> QuantizationMethods:
        raise NotImplementedError

    @abstractmethod
    def get_supported_act_dtypes(self) -> list[torch.dtype]:
        raise NotImplementedError

    @classmethod
    @abstractmethod
    def get_min_capability(cls) -> int:
        raise NotImplementedError

    @staticmethod
    @abstractmethod
    def get_config_filenames() -> list[str]:
        raise NotImplementedError

    @classmethod
    @abstractmethod
    def from_config(cls, config: dict[str, Any]) -> 'QuantizationConfig':
        raise NotImplementedError

    @classmethod
    def override_quantization_method(cls, hf_quant_cfg, user_quant) -> Optional[QuantizationMethods]:
        return None

    @staticmethod
    def get_from_keys(config: dict[str, Any], keys: list[str]) -> Any:
        for key in keys:
            if key in config:
                return config[key]
        raise ValueError(f"Cannot find any of {keys} in the model's quantization config.")

    @staticmethod
    def get_from_keys_or(config: dict[str, Any], keys: list[str], default: Any) -> Any:
        try:
            return QuantizationConfig.get_from_keys(config, keys)
        except ValueError:
            return default

    @abstractmethod
    def get_quant_method(self, layer: torch.nn.Module, prefix: str) -> Optional[QuantizeMethodBase]:
        raise NotImplementedError

    def get_cache_scale(self, name: str) -> Optional[str]:
        return None

    def apply_vllm_mapper(self, hf_to_vllm_mapper: 'WeightsMapper'):
        pass

    def maybe_update_config(self, model_name: str):
        pass

class QuantizeMethodBase(ABC):

    @abstractmethod
