def apply_chat_template(self, conversation: Union[list[dict[str, str]], list[list[dict[str, str]]]], tools: Optional[list[Union[dict, Callable]]]=None, documents: Optional[list[dict[str, str]]]=None, chat_template: Optional[str]=None, add_generation_prompt: bool=False, continue_final_message: bool=False, tokenize: bool=True, padding: Union[bool, str, PaddingStrategy]=False, truncation: bool=False, max_length: Optional[int]=None, return_tensors: Optional[Union[str, TensorType]]=None, return_dict: bool=False, return_assistant_tokens_mask: bool=False, tokenizer_kwargs: Optional[dict[str, Any]]=None, **kwargs) -> Union[str, list[int], list[str], list[list[int]], BatchEncoding]:
    if return_dict and (not tokenize):
        raise ValueError('`return_dict=True` is incompatible with `tokenize=False`, because there is no dict of tokenizer outputs to return.')
    if return_assistant_tokens_mask and (not return_dict):
        raise ValueError('`return_assistant_tokens_mask=True` is incompatible with `return_dict=False`')
    if tokenizer_kwargs is None:
        tokenizer_kwargs = {}
    chat_template = self.get_chat_template(chat_template, tools)
    if isinstance(conversation, (list, tuple)) and (isinstance(conversation[0], (list, tuple)) or hasattr(conversation[0], 'messages')):
        conversations = conversation
        is_batched = True
    else:
        conversations = [conversation]
        is_batched = False
    if continue_final_message:
        if add_generation_prompt:
            raise ValueError('continue_final_message and add_generation_prompt are not compatible. Use continue_final_message when you want the model to continue the final message, and add_generation_prompt when you want to add a header that will prompt it to start a new assistant message instead.')
        if return_assistant_tokens_mask:
            raise ValueError('continue_final_message is not compatible with return_assistant_tokens_mask.')
    template_kwargs = {**self.special_tokens_map, **kwargs}
    rendered_chat, generation_indices = render_jinja_template(conversations=conversations, tools=tools, documents=documents, chat_template=chat_template, return_assistant_tokens_mask=return_assistant_tokens_mask, continue_final_message=continue_final_message, add_generation_prompt=add_generation_prompt, **template_kwargs)
    if not is_batched:
        rendered_chat = rendered_chat[0]
    if tokenize:
        out = self(rendered_chat, padding=padding, truncation=truncation, max_length=max_length, add_special_tokens=False, return_tensors=return_tensors, **tokenizer_kwargs)
        if return_dict:
            if return_assistant_tokens_mask:
                assistant_masks = []
                if is_batched or return_tensors:
                    input_ids = out['input_ids']
                else:
                    input_ids = [out['input_ids']]
                for i in range(len(input_ids)):
                    current_mask = [0] * len(input_ids[i])
                    for assistant_start_char, assistant_end_char in generation_indices[i]:
                        start_token = out.char_to_token(i, assistant_start_char)
                        end_token = out.char_to_token(i, assistant_end_char - 1)
                        if start_token is None:
                            break
                        for token_id in range(start_token, end_token + 1 if end_token else len(input_ids[i])):
                            current_mask[token_id] = 1
                    assistant_masks.append(current_mask)
                if not is_batched and (not return_tensors):
                    assistant_masks = assistant_masks[0]
                out['assistant_masks'] = assistant_masks
                if return_tensors:
                    out.convert_to_tensors(tensor_type=return_tensors)
            return out
        else:
            return out['input_ids']
    else:
        return rendered_chat

def _get_weights_iterator(self, source: 'Source') -> Generator[tuple[str, torch.Tensor], None, None]:
    extra_config = self.load_config.model_loader_extra_config
    hf_folder, hf_weights_files, use_safetensors = self._prepare_weights(source.model_or_path, source.revision, source.fall_back_to_pt, source.allow_patterns_overrides)
    if self.load_config.load_format == 'npcache':
        assert use_safetensors is False
        weights_iterator = np_cache_weights_iterator(source.model_or_path, self.load_config.download_dir, hf_folder, hf_weights_files, self.load_config.use_tqdm_on_load)
    elif use_safetensors:
        if self.load_config.load_format == 'fastsafetensors':
            weights_iterator = fastsafetensors_weights_iterator(hf_weights_files, self.load_config.use_tqdm_on_load)
        elif extra_config.get('enable_multithread_load'):
            weights_iterator = multi_thread_safetensors_weights_iterator(hf_weights_files, self.load_config.use_tqdm_on_load, max_workers=extra_config.get('num_threads', self.DEFAULT_NUM_THREADS))
        else:
            weights_iterator = safetensors_weights_iterator(hf_weights_files, self.load_config.use_tqdm_on_load, self.load_config.safetensors_load_strategy)
    elif extra_config.get('enable_multithread_load'):
        weights_iterator = multi_thread_pt_weights_iterator(hf_weights_files, self.load_config.use_tqdm_on_load, self.load_config.pt_load_map_location, max_workers=extra_config.get('num_threads', self.DEFAULT_NUM_THREADS))
    else:
        weights_iterator = pt_weights_iterator(hf_weights_files, self.load_config.use_tqdm_on_load, self.load_config.pt_load_map_location)
    if current_platform.is_tpu():
        from vllm.platforms.tpu import USE_TPU_COMMONS
        if not USE_TPU_COMMONS:
            import torch_xla

            def _xla_weights_iterator(iterator: Generator):
                for weights in iterator:
                    yield weights
                    torch_xla.sync(wait=False)
            weights_iterator = _xla_weights_iterator(weights_iterator)
    if self.counter_before_loading_weights == 0.0:
        self.counter_before_loading_weights = time.perf_counter()
    return ((source.prefix + name, tensor) for name, tensor in weights_iterator)

def _batch_encode_plus(self, batch_text_or_text_pairs: Union[list[TextInput], list[TextInputPair], list[PreTokenizedInput], list[PreTokenizedInputPair]], add_special_tokens: bool=True, padding_strategy: PaddingStrategy=PaddingStrategy.DO_NOT_PAD, truncation_strategy: TruncationStrategy=TruncationStrategy.DO_NOT_TRUNCATE, max_length: Optional[int]=None, stride: int=0, is_split_into_words: bool=False, pad_to_multiple_of: Optional[int]=None, padding_side: Optional[str]=None, return_tensors: Optional[str]=None, return_token_type_ids: Optional[bool]=None, return_attention_mask: Optional[bool]=None, return_overflowing_tokens: bool=False, return_special_tokens_mask: bool=False, return_offsets_mapping: bool=False, return_length: bool=False, verbose: bool=True, split_special_tokens: bool=False) -> BatchEncoding:
    if not isinstance(batch_text_or_text_pairs, (tuple, list)):
        raise TypeError(f'batch_text_or_text_pairs has to be a list or a tuple (got {type(batch_text_or_text_pairs)})')
    self.set_truncation_and_padding(padding_strategy=padding_strategy, truncation_strategy=truncation_strategy, max_length=max_length, stride=stride, pad_to_multiple_of=pad_to_multiple_of, padding_side=padding_side)
    if self._tokenizer.encode_special_tokens != split_special_tokens:
        self._tokenizer.encode_special_tokens = split_special_tokens
    encodings = self._tokenizer.encode_batch(batch_text_or_text_pairs, add_special_tokens=add_special_tokens, is_pretokenized=is_split_into_words)
    tokens_and_encodings = [self._convert_encoding(encoding=encoding, return_token_type_ids=return_token_type_ids, return_attention_mask=return_attention_mask, return_overflowing_tokens=return_overflowing_tokens, return_special_tokens_mask=return_special_tokens_mask, return_offsets_mapping=return_offsets_mapping, return_length=return_length, verbose=verbose) for encoding in encodings]
    sanitized_tokens = {}
    for key in tokens_and_encodings[0][0]:
        stack = [e for item, _ in tokens_and_encodings for e in item[key]]
        sanitized_tokens[key] = stack
    sanitized_encodings = [e for _, item in tokens_and_encodings for e in item]
    if return_overflowing_tokens:
        overflow_to_sample_mapping = []
        for i, (toks, _) in enumerate(tokens_and_encodings):
            overflow_to_sample_mapping += [i] * len(toks['input_ids'])
        sanitized_tokens['overflow_to_sample_mapping'] = overflow_to_sample_mapping
    for input_ids in sanitized_tokens['input_ids']:
        self._eventual_warn_about_too_long_sequence(input_ids, max_length, verbose)
    return BatchEncoding(sanitized_tokens, sanitized_encodings, tensor_type=return_tensors)

def _decode(self, token_ids: Union[int, list[int]], skip_special_tokens: bool=False, clean_up_tokenization_spaces: Optional[bool]=None, **kwargs) -> str:
    self._decode_use_source_tokenizer = kwargs.pop('use_source_tokenizer', False)
    if isinstance(token_ids, int):
        token_ids = [token_ids]
    text = self._tokenizer.decode(token_ids, skip_special_tokens=skip_special_tokens)
    clean_up_tokenization_spaces = clean_up_tokenization_spaces if clean_up_tokenization_spaces is not None else self.clean_up_tokenization_spaces
    if clean_up_tokenization_spaces:
        clean_text = self.clean_up_tokenization(text)
        return clean_text
    else:
        return text

def _compile_jinja_template(chat_template):
    if not is_jinja_available():
        raise ImportError('apply_chat_template requires jinja2 to be installed. Please install it using `pip install jinja2`.')

    class AssistantTracker(Extension):
        tags = {'generation'}

        def __init__(self, environment: ImmutableSandboxedEnvironment):
            super().__init__(environment)
            environment.extend(activate_tracker=self.activate_tracker)
            self._rendered_blocks = None
            self._generation_indices = None

        def parse(self, parser: jinja2.parser.Parser) -> jinja2.nodes.CallBlock:
            lineno = next(parser.stream).lineno
            body = parser.parse_statements(['name:endgeneration'], drop_needle=True)
            return jinja2.nodes.CallBlock(self.call_method('_generation_support'), [], [], body).set_lineno(lineno)

        @jinja2.pass_eval_context
        def _generation_support(self, context: jinja2.nodes.EvalContext, caller: jinja2.runtime.Macro) -> str:
            rv = caller()
            if self.is_active():
                start_index = len(''.join(self._rendered_blocks))
                end_index = start_index + len(rv)
                self._generation_indices.append((start_index, end_index))
            return rv

        def is_active(self) -> bool:
            return self._rendered_blocks or self._generation_indices

        @contextmanager
        def activate_tracker(self, rendered_blocks: list[int], generation_indices: list[int]):
            try:
                if self.is_active():
                    raise ValueError('AssistantTracker should not be reused before closed')
                self._rendered_blocks = rendered_blocks
                self._generation_indices = generation_indices
                yield
            finally:
                self._rendered_blocks = None
                self._generation_indices = None
    if version.parse(jinja2.__version__) < version.parse('3.1.0'):
        raise ImportError(f'apply_chat_template requires jinja2>=3.1.0 to be installed. Your version is {jinja2.__version__}.')

    def raise_exception(message):
        raise jinja2.exceptions.TemplateError(message)

    def tojson(x, ensure_ascii=False, indent=None, separators=None, sort_keys=False):
        return json.dumps(x, ensure_ascii=ensure_ascii, indent=indent, separators=separators, sort_keys=sort_keys)

    def strftime_now(format):
        return datetime.now().strftime(format)
    jinja_env = ImmutableSandboxedEnvironment(trim_blocks=True, lstrip_blocks=True, extensions=[AssistantTracker, jinja2.ext.loopcontrols])
    jinja_env.filters['tojson'] = tojson
    jinja_env.globals['raise_exception'] = raise_exception
    jinja_env.globals['strftime_now'] = strftime_now
    return jinja_env.from_string(chat_template)

def render_jinja_template(conversations: list[list[dict[str, str]]], tools: Optional[list[Union[dict, Callable]]]=None, documents: Optional[list[dict[str, str]]]=None, chat_template: Optional[str]=None, return_assistant_tokens_mask: bool=False, continue_final_message: bool=False, add_generation_prompt: bool=False, **kwargs) -> str:
    if return_assistant_tokens_mask and (not re.search('<LOCAL_PATH>', chat_template)):
        logger.warning_once('return_assistant_tokens_mask==True but chat template does not contain `{% generation %}` keyword.')
    compiled_template = _compile_jinja_template(chat_template)
    if tools is not None:
        tool_schemas = []
        for tool in tools:
            if isinstance(tool, dict):
                tool_schemas.append(tool)
            elif isfunction(tool):
                tool_schemas.append(get_json_schema(tool))
            else:
                raise ValueError('Tools should either be a JSON schema, or a callable function with type hints and a docstring suitable for auto-conversion to a schema.')
    else:
        tool_schemas = None
    if documents is not None:
        for document in documents:
            if not isinstance(document, dict):
                raise TypeError("Documents should be a list of dicts with 'title' and 'text' keys!")
    rendered = []
    all_generation_indices = []
    continue_final_message_tag = 'CONTINUE_FINAL_MESSAGE_TAG '
    for chat in conversations:
        if hasattr(chat, 'messages'):
            chat = chat.messages
        if continue_final_message:
            chat = deepcopy(chat)
            final_message = chat[-1]['content']
            if isinstance(final_message, (list, tuple)):
                for content_block in reversed(final_message):
                    if 'text' in content_block:
                        final_message = content_block['text']
                        content_block['text'] = content_block['text'] + continue_final_message_tag
                        break
                else:
                    raise ValueError('continue_final_message is set but we could not find any text to continue in the final message!')
            else:
                chat[-1]['content'] = chat[-1]['content'] + continue_final_message_tag
        if return_assistant_tokens_mask:
            rendered_chat, generation_indices = _render_with_assistant_indices(compiled_template=compiled_template, messages=chat, tools=tool_schemas, documents=documents, add_generation_prompt=add_generation_prompt, **kwargs)
            all_generation_indices.append(generation_indices)
        else:
            rendered_chat = compiled_template.render(messages=chat, tools=tool_schemas, documents=documents, add_generation_prompt=add_generation_prompt, **kwargs)
        if continue_final_message:
            if final_message.strip() not in rendered_chat or continue_final_message_tag.strip() not in rendered_chat:
                raise ValueError('continue_final_message is set but the final message does not appear in the chat after applying the chat template! This can happen if the chat template deletes portions of the final message. Please verify the chat template and final message in your chat to ensure they are compatible.')
            tag_loc = rendered_chat.rindex(continue_final_message_tag.strip())
            if rendered_chat[tag_loc:tag_loc + len(continue_final_message_tag)] == continue_final_message_tag:
                rendered_chat = rendered_chat[:tag_loc]
            else:
                rendered_chat = rendered_chat[:tag_loc].rstrip()
        rendered.append(rendered_chat)
    return (rendered, all_generation_indices)

def from_string(self, source: t.Union[str, nodes.Template], globals: t.Optional[t.MutableMapping[str, t.Any]]=None, template_class: t.Optional[t.Type['Template']]=None) -> 'Template':
    gs = self.make_globals(globals)
    cls = template_class or self.template_class
    return cls.from_code(self, self.compile(source), gs, None)

def render(self, *args: t.Any, **kwargs: t.Any) -> str:
    if self.environment.is_async:
        import asyncio
        return asyncio.run(self.render_async(*args, **kwargs))
    ctx = self.new_context(dict(*args, **kwargs))
    try:
        return self.environment.concat(self.root_render_func(ctx))
    except Exception:
        self.environment.handle_exception()

def call(__self, __context: Context, __obj: t.Any, *args: t.Any, **kwargs: t.Any) -> t.Any:
    if not __self.is_safe_callable(__obj):
        raise SecurityError(f'{__obj!r} is not safely callable')
    return __context.call(__obj, *args, **kwargs)

def preprocess(self, prompt: PromptType, tokenization_kwargs: Optional[dict[str, Any]]=None, *, mm_uuids: Optional[MultiModalUUIDDict]=None) -> ProcessorInputs:
    if self.model_config.is_encoder_decoder:
        return self._process_encoder_decoder_prompt(prompt, tokenization_kwargs, mm_uuids=mm_uuids)
    if is_explicit_encoder_decoder_prompt(prompt):
        raise ValueError('Cannot pass encoder-decoder prompt to decoder-only models')
    return self._process_decoder_only_prompt(prompt, tokenization_kwargs=tokenization_kwargs, mm_uuids=mm_uuids)

def _process_tokens(self, parsed_content: TokensPrompt, tokenization_kwargs: Optional[dict[str, Any]]=None, *, mm_uuids: Optional[MultiModalUUIDDict]=None) -> Union[TokenInputs, MultiModalInputs]:
    prompt_token_ids = self._truncate_inputs(parsed_content['prompt_token_ids'], tokenization_kwargs)
    inputs: Union[TokenInputs, MultiModalInputs]
    if (multi_modal_data := parsed_content.get('multi_modal_data')):
        inputs = self._process_multimodal(prompt_token_ids, multi_modal_data, parsed_content.get('mm_processor_kwargs'), tokenization_kwargs=tokenization_kwargs, mm_uuids=mm_uuids)
    else:
        inputs = token_inputs(prompt_token_ids=prompt_token_ids)
    if (cache_salt := parsed_content.get('cache_salt')):
        inputs['cache_salt'] = cache_salt
    return inputs

def from_new_request(cls, tokenizer: Optional[AnyTokenizer], request: EngineCoreRequest) -> 'IncrementalDetokenizer':
    assert request.sampling_params is not None
    if tokenizer is None:
        return IncrementalDetokenizer()
    if USE_FAST_DETOKENIZER and isinstance(tokenizer, PreTrainedTokenizerFast):
        return FastIncrementalDetokenizer(tokenizer, request)
    return SlowIncrementalDetokenizer(tokenizer, request)

def update(self, new_token_ids: list[int], stop_terminated: bool) -> Optional[str]:
    if not new_token_ids:
        return None
    if stop_terminated and (not self.include_stop_str_in_output):
        skipped_stop_token_id = new_token_ids[-1]
        new_token_ids = new_token_ids[:-1]
    else:
        skipped_stop_token_id = None
    stop_check_offset = len(self.output_text)
    for new_token_id in new_token_ids:
        self.token_ids.append(new_token_id)
        self.output_text += self.decode_next(new_token_id)
        if self.min_tokens and len(self.output_token_ids) <= self.min_tokens:
            stop_check_offset = len(self.output_text)
    if skipped_stop_token_id is not None:
        self.token_ids.append(skipped_stop_token_id)
    stop_string = None
    if self.stop and len(self.output_token_ids) > self.min_tokens:
        stop = check_stop_strings(output_text=self.output_text, new_char_count=len(self.output_text) - stop_check_offset, stop=self.stop, include_in_output=self.include_stop_str_in_output)
        if stop is not None:
            stop_string, truncate_to = stop
            if truncate_to != -1:
                self.output_text = self.output_text[:truncate_to]
    return stop_string

def __init__(self, tokenizer: PreTrainedTokenizerFast, request: EngineCoreRequest):
    super().__init__(request)
    sampling_params = request.sampling_params
    assert sampling_params is not None
    self.request_id = request.request_id
    self.skip_special_tokens = sampling_params.skip_special_tokens
    self.stream = DecodeStream(skip_special_tokens=self.skip_special_tokens)
    self.tokenizer: Tokenizer = tokenizer._tokenizer
    prompt_token_ids = request.prompt_token_ids or []
    prompt_suffix = prompt_token_ids
    prompt_len = len(prompt_suffix)
    if prompt_len > 4:
        for i in range(4, min(prompt_len + 1, 24)):
            suffix = prompt_token_ids[-i:]
            if '�' not in self.tokenizer.decode(suffix):
                prompt_suffix = suffix
                break
    for tid in prompt_suffix:
        self._protected_step(tid)
    self.spaces_between_special_tokens = sampling_params.skip_special_tokens or sampling_params.spaces_between_special_tokens
    if not self.spaces_between_special_tokens:
        if (added_token_ids := getattr(self.tokenizer, 'added_token_ids', None)) is None:
            self.tokenizer.added_token_ids = added_token_ids = {tid: tok.content for tid, tok in self.tokenizer.get_added_tokens_decoder().items()}
        if added_token_ids:
            self.last_special = False
            self.added_token_ids = added_token_ids
        else:
            self.spaces_between_special_tokens = True

def _protected_step(self, next_token_id: int) -> Optional[str]:
    try:
        token = self.stream.step(self.tokenizer, next_token_id)
    except OverflowError:
        logger.exception('Encountered invalid token id: %d', next_token_id)
        token = None
    except Exception as e:
        if not str(e).startswith(INVALID_PREFIX_ERR_MSG):
            raise e
        logger.warning('Encountered invalid prefix detokenization error for request %s, resetting decode stream.', self.request_id)
        self.stream = DecodeStream(skip_special_tokens=self.skip_special_tokens)
        token = self.stream.step(self.tokenizer, next_token_id)
    return token

def load_file(filename: Union[str, os.PathLike], device: Union[str, int]='cpu', *, backend: str='mmap') -> Dict[str, torch.Tensor]:
    with safe_open(filename, framework='pt', device=device, backend=backend) as f:
        return f.get_tensors()
